{
  "id": "openclaw:core:ask_user",
  "source": "openclaw",
  "sourceName": "core",
  "name": "ask_user",
  "label": "Ask User",
  "description": "Ask the human user 1-3 structured questions and wait for their answer; `multiSelect` allows picking several options and `timeoutSeconds` bounds the wait. Use only when blocked on a decision genuinely theirs that cannot be resolved from the request, code, or sensible defaults; never ask whether to proceed or confirm a plan. Ask exactly one question per call unless several answers must be submitted together; one single-select question uses native controls on supported messaging channels. Put every selectable choice in `options`, never only in the question text. Put the recommended option first and suffix its label with ` (Recommended)`. Use `multiSelect` only when the user may choose several options at once; otherwise omit it. Do not include an Other option; free text is added automatically. If the result is no_answer, continue with best judgment.",
  "input": "{ questions: Array<{ header: string; id: string; options: Array<{ label: unknown; description?: unknown; preview?: unknown; resourceUri?: unknown; thumbnail?: unknown; value?: unknown }>; question: string; multiSelect?: boolean }>; timeoutSeconds?: number /* integer */ }",
  "parameters": {
    "type": "object",
    "required": [
      "questions"
    ],
    "properties": {
      "questions": {
        "type": "array",
        "items": {
          "type": "object",
          "required": [
            "id",
            "header",
            "question",
            "options"
          ],
          "properties": {
            "id": {
              "type": "string",
              "pattern": "^[a-z][a-z0-9_]*$",
              "description": "Unique snake_case answer key."
            },
            "header": {
              "type": "string",
              "minLength": 1,
              "description": "Short chip label; longer input is truncated to 12 characters."
            },
            "question": {
              "type": "string",
              "minLength": 1,
              "description": "Single-sentence question only. Put all selectable choices in options."
            },
            "options": {
              "type": "array",
              "items": {
                "type": "object",
                "required": [
                  "label"
                ],
                "properties": {
                  "label": {
                    "type": "string",
                    "minLength": 1
                  },
                  "description": {
                    "type": "string"
                  },
                  "value": {
                    "type": "string",
                    "minLength": 1,
                    "maxLength": 4096,
                    "x-openclaw-since": "2026.9"
                  },
                  "thumbnail": {
                    "type": "string",
                    "minLength": 1,
                    "maxLength": 65536
                  },
                  "resourceUri": {
                    "type": "string",
                    "minLength": 1,
                    "maxLength": 2048
                  },
                  "preview": {
                    "type": "object",
                    "properties": {
                      "type": {
                        "type": "string",
                        "enum": [
                          "mcp_app_tool",
                          "resource_link"
                        ]
                      },
                      "name": {
                        "type": "string",
                        "minLength": 1
                      },
                      "arguments": {
                        "type": "object",
                        "patternProperties": {
                          "^.*$": {}
                        }
                      },
                      "uri": {
                        "type": "string",
                        "minLength": 1
                      },
                      "title": {
                        "type": "string"
                      },
                      "description": {
                        "type": "string"
                      },
                      "mimeType": {
                        "type": "string"
                      }
                    },
                    "required": [
                      "type",
                      "name"
                    ]
                  }
                },
                "additionalProperties": false
              },
              "minItems": 2,
              "maxItems": 4,
              "description": "Every selectable choice. Put the recommended choice first; do not repeat choices only in the question text."
            },
            "multiSelect": {
              "type": "boolean",
              "description": "True only when the user may choose several options at once.",
              "~optional": true
            }
          },
          "additionalProperties": false
        },
        "minItems": 1,
        "maxItems": 3
      },
      "timeoutSeconds": {
        "type": "integer",
        "description": "Maximum human wait in seconds; default 900, clamped 30-3600. Earlier run cancellation or overall run timeout still applies."
      }
    },
    "additionalProperties": false
  }
}

